def ev(p,*rs):
 p='pfp/domain/'+p;return {'path':p,'sha256':a.row(p)['sha256'],'lines':[list(x) for x in rs]}
for number,title,statement,es,ids in [
(62,'Symplectic decoder silently maps nonbinary entries to Pauli Z','from_symplectic_vector applies modulo2 without checking integer/binary domain. Input [0.5,0] for one qubit is accepted as Z, although it is not a vector in F2 squared and does not roundtrip. Valid binary Pauli algebra controls pass separately.',[ev('quantum/pauli.py',(118,135))],[80]),
(63,'Hamiltonian explicit IDs collide with implicit term indices','parse_challenge deduplicates only IDs explicitly present in mapping rows. An implicit first-term index0 and second explicit id0 are both retained, yielding term_ids=(0,0). Consumers that use IDs for witness binding need an additional uniqueness check.',[ev('quantum/hamiltonian.py',(184,199),(241,269))],[81]),
(64,'Sealed prompt envelope permits stale hash and authority mutation','PacketEnvelope verifies hash and authority only on construction; its model and nested dictionaries remain mutable. Changing candidate x from1 to2 and authority_effect fromNone toGranted leaves the original envelope hash intact. This is a stale seal on the object, before any caller revalidation. The serializer also accepts NaN despite standards-style canonical JSON labels.',[ev('prompts/packets.py',(16,23),(26,60))],[82]),
(65,'Proposal evaluator certifies strict descent without descent or exactness','Equal masses are admissible and labelled Strict descent verified. require_exactness=True does not prevent float1e-12 being rounded to exact zero; max_proposals=0 does not prevent selecting a candidate. Those config fields are unused. The evaluator checks a tolerance-bounded reported scalar change, not strict descent of reconstructed residuals.',[ev('evaluator.py',(27,54),(80,133),(147,157))],[83])]:n['findings'].append({'id':'PFPDOMAIN-F'+str(number).zfill(3),'title':title,'statement':statement,'evidence':[e['path'] for e in es],'source_evidence':es,'control_ids':['PFPDOMAIN-C'+str(i).zfill(3) for i in ids],'status':'confirmed_bounded_source_and_probe','limits':'Pure finite owners on Python3.14.2. No candidate dispatched, provider called or external authority exercised. Consumers may revalidate or impose stronger domain restrictions.'})
for num,title,s,es,ids in [
(17,'Finite quantum algebra is independent of physical and certificate labels','Pauli tensor multiplication and commutation agree with explicit4x4 matrices on all256 two-qubit pairs. GF2 RREF plus rigorous fixed-coordinate branch-and-bound agrees with exhaustive syndrome-compatible search on512 tiny cases. For a complete kernel and positive supplied weights, the affine coset exhausts every same-syndrome vector, supporting a finite optimum. C029 code geometry and original matching-certificate obligations remain outside this independent check.',[ev('quantum/pauli.py',(78,116)),ev('quantum/c029_coset.py',(15,75),(127,175))],[78,79]),
(18,'Prompt compression revalidates preserved provider inputs','The compression owner preserves UTF8 source spans, shared environments and explicit per-turn schema overrides while recomputing digest bindings at expansion. A Unicode two-turn control roundtrips and refuses a nested environment mutation. Its claim is storage deduplication only; expanded provider requests, semantics and author authentication are not improved or certified.',[ev('prompts/compression.py',(88,141),(144,190)),ev('prompt_representations/common.py',(60,84))],[84])]:n['claims'].append({'id':'PFPDOMAIN-CL'+str(num).zfill(2),'title':title,'statement':s,'evidence':[e['path'] for e in es],'source_evidence':es,'control_ids':['PFPDOMAIN-C'+str(i).zfill(3) for i in ids],'status':'bounded_scope_assessment'})
